def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [0] * 10
    for row in grid:
        for v in row:
            counts[v] += 1

    # Find the monochromatic divider with the least frequent color.
    lines = []
    for r in range(h):
        if len(set(grid[r])) == 1:
            lines.append((counts[grid[r][0]], "row", r))
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            lines.append((counts[grid[0][c]], "col", c))

    _, direction, pos = min(lines)

    if direction == "row":
        a, b = grid[:pos], grid[pos + 1:]
        n = min(len(a), len(b))
        return [[2 if a[i][j] and b[i][j] else 0
                 for j in range(w)] for i in range(n)]

    a = [row[:pos] for row in grid]
    b = [row[pos + 1:] for row in grid]
    n = min(len(a[0]), len(b[0]))
    return [[2 if a[i][j] and b[i][j] else 0
             for j in range(n)] for i in range(h)]
